        } catch (IllegalStateException e) {
            Assert.assertEquals("JavaScript is disabled", e.getMessage());
        }
    }

    public static class TestFilter {
        private final String function;
        private final JavaScriptConfig config;

        @com.fasterxml.jackson.annotation.JsonCreator
        public TestFilter(
            @com.fasterxml.jackson.annotation.JsonProperty("function") String function,
            @com.fasterxml.jackson.annotation.JsonIgnore @com.fasterxml.jackson.annotation.JacksonInject JavaScriptConfig config
        ) {
            this.function = function;
            this.config = config;
        }
    }

    @Test
    public void testFixWithJsonIgnore() throws Exception {
        ObjectMapper mapper = new DefaultObjectMapper();
        JavaScriptConfig disabledConfig = new JavaScriptConfig(false);
        InjectableValues inject = new InjectableValues.Std()
            .addValue(JavaScriptConfig.class, disabledConfig);
        mapper.setInjectableValues(inject);

        String json = "{\n" +
                "  \"function\": \"foo\",\n" +
                "  \"\": {\n" +
                "    \"enabled\": true\n" +
                "  }\n" +
                "}";

        TestFilter filter = mapper.readValue(json, TestFilter.class);
        Assert.assertFalse("Fix worked: JavaScriptConfig should be disabled", filter.config.isEnabled());
    }
}

