public class ReproductionTest {
    public static class TestFilter {
        public final JavaScriptConfig config;

        @com.fasterxml.jackson.annotation.JsonCreator
        public TestFilter(
            @JsonProperty("config") @JacksonInject(useInput = OptBoolean.FALSE) JavaScriptConfig config
        ) {
            this.config = config;
        }
    }

    @Test
    public void testFixWithUseInputFalse() throws Exception {
        ObjectMapper mapper = new DefaultObjectMapper();
        JavaScriptConfig disabledConfig = new JavaScriptConfig(false);
        InjectableValues inject = new InjectableValues.Std()
            .addValue(JavaScriptConfig.class, disabledConfig);
        mapper.setInjectableValues(inject);

        // Try to override via ""
        String json1 = "{\"\": {\"enabled\": true}}";
        TestFilter filter1 = mapper.readValue(json1, TestFilter.class);
        Assert.assertFalse("Should not be enabled via empty key", filter1.config.isEnabled());

        // Try to override via "config"
        String json2 = "{\"config\": {\"enabled\": true}}";
        TestFilter filter2 = mapper.readValue(json2, TestFilter.class);
        Assert.assertFalse("Should not be enabled via 'config' key", filter2.config.isEnabled());
    }
}

